import data from "./cities.json";

// The slim city list for the UI's main thread: code, name and states, without the BEA and HUD
// tables (those stay in the engine worker). Generated by `npm run build-cities`.

export interface City { code: string; name: string; states: string[] }

export const CITIES: City[] = data.cities;
/** BEA RPP data year and HUD FMR fiscal year, for the sources line. */
export const DATA_YEARS = { rpp: data.rppDataYear, fmr: data.fmrFiscalYear };

const byCode = new Map(CITIES.map((c) => [c.code, c]));

export const cityByCode = (code: string): City | undefined => byCode.get(code);
/** States a place lies in (a metro can span several). */
export const statesOf = (code: string | null): string[] => (code ? byCode.get(code)?.states ?? [] : []);
